#include "quest_snapshot_store.h"
#include "utils/logger.h"
#include <algorithm>
#include <cstdio>
#include <fstream>
#include <sys/stat.h>
namespace {std::vector<std::string> Split(const std::string&v,char s){std::vector<std::string>o;size_t p=0;for(;;){size_t a=v.find(s,p);o.push_back(v.substr(p,a==std::string::npos?a:a-p));if(a==std::string::npos)return o;p=a+1;}}std::string Hex(const std::string&v){static const char*d="0123456789abcdef";std::string o;for(unsigned char c:v){o+=d[c>>4];o+=d[c&15];}return o;}int N(char c){return c>='0'&&c<='9'?c-'0':c>='a'&&c<='f'?c-'a'+10:c>='A'&&c<='F'?c-'A'+10:-1;}bool Unhex(const std::string&v,std::string&o){if(v.size()%2)return false;o.clear();for(size_t i=0;i<v.size();i+=2){int a=N(v[i]),b=N(v[i+1]);if(a<0||b<0)return false;o+=char((a<<4)|b);}return true;}bool Safe(const std::string&v){return !v.empty()&&v.size()<=128&&v.find_first_not_of("0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_-.")==std::string::npos;}}
QuestSnapshotStore::QuestSnapshotStore(std::string p):path_(std::move(p)){}
bool QuestSnapshotStore::Load(){std::ifstream in(path_);if(!in)return true;std::string l;while(std::getline(in,l)){auto f=Split(l,'\t');if(f.size()==6&&f[0]=="P"&&Safe(f[1])&&Safe(f[2])){StoredQuestSnapshot s;s.characterGuid=f[1];s.catalogFingerprint=f[2];try{s.capturedAt=std::stoll(f[3]);s.complete=f[4]=="1";}catch(...){continue;}snapshots_[s.characterGuid]=std::move(s);}else if(f.size()==6&&f[0]=="Q"&&Safe(f[1])&&Safe(f[2])){auto it=snapshots_.find(f[1]);if(it==snapshots_.end())continue;std::string status,objective;if(!Unhex(f[3],status)||!Unhex(f[4],objective))continue;try{it->second.quests.push_back({f[2],status,objective,std::stoll(f[5])});}catch(...){}}}LogMessage("Loaded "+std::to_string(snapshots_.size())+" player quest snapshots");return true;}
bool QuestSnapshotStore::Save()const{std::string t=path_+".tmp";std::ofstream out(t,std::ios::trunc);if(!out)return false;for(const auto&p:snapshots_){const auto&s=p.second;out<<"P\t"<<s.characterGuid<<'\t'<<s.catalogFingerprint<<'\t'<<s.capturedAt<<'\t'<<(s.complete?1:0)<<"\t-\n";for(const auto&q:s.quests)out<<"Q\t"<<s.characterGuid<<'\t'<<q.id<<'\t'<<Hex(q.status)<<'\t'<<Hex(q.objective)<<'\t'<<q.completedObservedAt<<'\n';}out.close();chmod(t.c_str(),0600);if(std::rename(t.c_str(),path_.c_str()))return false;chmod(path_.c_str(),0600);return true;}
bool QuestSnapshotStore::Sync(const std::vector<DomEngine::PlayerQuestSnapshot>&in){bool changed=false;for(const auto&live:in){if(!live.complete||live.characterGuid.empty()||live.quests.empty())continue;StoredQuestSnapshot next{live.characterGuid,live.catalogFingerprint,{},live.capturedAt,true};auto prior=snapshots_.find(live.characterGuid);for(const auto&q:live.quests){auto observed=q.completedObservedAt;if(q.status=="completed"&&!observed){if(prior!=snapshots_.end()){auto old=std::find_if(prior->second.quests.begin(),prior->second.quests.end(),[&](const auto&v){return v.id==q.id;});if(old!=prior->second.quests.end())observed=old->completedObservedAt;}if(!observed)observed=live.capturedAt;}next.quests.push_back({q.id,q.status,q.objective,observed});}bool same=prior!=snapshots_.end()&&prior->second.catalogFingerprint==next.catalogFingerprint&&prior->second.quests.size()==next.quests.size()&&std::equal(prior->second.quests.begin(),prior->second.quests.end(),next.quests.begin(),[](const auto&a,const auto&b){return a.id==b.id&&a.status==b.status&&a.objective==b.objective&&a.completedObservedAt==b.completedObservedAt;});if(!same){snapshots_[live.characterGuid]=std::move(next);changed=true;}}return !changed||Save();}
bool QuestSnapshotStore::Find(const std::string&g,StoredQuestSnapshot&o)const{auto i=snapshots_.find(g);if(i==snapshots_.end())return false;o=i->second;return true;}
